/* Lesson data: Rabin-Karp rolling hash (structure mode). Steps are generated by simulating the algorithm. */
(function () {
  var TEXT = '31415926535', PAT = '265', MOD = 7, BASE = 10;
  var X0 = 90, DX = 78, TY = 80, PY = 170;
  var n = TEXT.length, m = PAT.length;
  var top = Math.pow(BASE, m - 1) % MOD;

  function scene() {
    var ops = [], steps = [], prev = [], badId = null;
    for (var t = 0; t < n; t++) ops.push(['node', 't' + t, TEXT[t], X0 + t * DX, TY, 'cell']);
    for (var q = 0; q < m; q++) ops.push(['node', 'p' + q, PAT[q], X0 + q * DX, PY, 'cell']);
    var hp = 0;
    for (var a = 0; a < m; a++) hp = (hp * BASE + +PAT[a]) % MOD;
    ops.push(['note', 'p0', 'pattern hash = ' + hp]);
    steps.push({ pl: 0, cl: 0, h: 380, say: 'Rabin-Karp compares a number, not letters. Treat each window of ' + m + ' digits as a number and keep only its remainder mod ' + MOD + '. The pattern ' + PAT + ' has hash ' + PAT + ' mod ' + MOD + ' = ' + hp + '. Windows with a different hash cannot match.', csay: 'hp = hash(pattern).', ds: ops });
    var h = 0;
    for (var b = 0; b < m; b++) h = (h * BASE + +TEXT[b]) % MOD;
    function window_(s) { var o = prev.map(function (id) { return ['untag', id, 'cur']; }); prev = []; for (var k = 0; k < m; k++) { o.push(['tag', 't' + (s + k), 'cur']); prev.push('t' + (s + k)); } return o; }
    var o0 = window_(0); o0.push(['note', 't0', 'h=' + h]);
    steps.push({ pl: 3, cl: 2, h: 380, say: 'First window "' + TEXT.slice(0, m) + '": hash = ' + TEXT.slice(0, m) + ' mod ' + MOD + ' = ' + h + '. Computed from scratch once; every later window is derived from the previous one in O(1).', csay: 'h = hash(text[0..m-1]);', ds: o0 });
    for (var s = 0; s <= n - m; s++) {
      if (s > 0) {
        var oldD = +TEXT[s - 1], newD = +TEXT[s + m - 1];
        var nh = (((h - oldD * top) % MOD + MOD) % MOD * BASE + newD) % MOD;
        var o1 = window_(s); if (badId) { o1.push(['untag', badId, 'bad']); badId = null; } o1.push(['note', 't' + s, 'h=' + nh]);
        steps.push({ pl: 7, cl: 6, h: 380, say: 'Roll the window: remove the leading digit ' + oldD + ', shift, add the new digit ' + newD + '. New hash = ((' + h + ' - ' + oldD + ' x ' + top + ') x ' + BASE + ' + ' + newD + ') mod ' + MOD + ' = ' + nh + '.', csay: 'h = (h - old * top) * B + new, mod M.', ds: o1 });
        h = nh;
      }
      if (h === hp) {
        var real = TEXT.substr(s, m) === PAT;
        steps.push({ pl: 5, cl: 4, h: 380, say: 'Hash ' + h + ' equals the pattern hash, so this window MIGHT match: compare the characters. "' + TEXT.substr(s, m) + '" vs "' + PAT + '": ' + (real ? 'identical. Found at index ' + s + '.' : 'different. A collision (spurious hit): different numbers can share a remainder, which is why the check is required.'), csay: real ? 'return s;' : 'Hash collision: strings differ.', ds: real ? [['tag', 't' + s, 'done'], ['tag', 't' + (s + 1), 'done'], ['tag', 't' + (s + 2), 'done'], ['hot', 'p0', 'p1', 'p2']] : [['hot', 't' + s, 't' + (s + 1), 't' + (s + 2)], ['tag', 't' + s, 'bad']] });
        if (!real) badId = 't' + s;
        if (real) break;
      } else if (s === 1 || s === 2) {
        steps.push({ pl: 5, cl: 4, h: 380, say: 'Hash ' + h + ' differs from ' + hp + ': skip this window with no character comparison at all.', csay: 'Hashes differ: skip.', ds: [] });
      }
    }
    return steps;
  }

  var py = ['def rabin_karp(text, pat, B=10, M=7):', '    n, m = len(text), len(pat)', '    hp = h = 0; top = pow(B, m - 1, M)', '    # hp, h = hash of pattern and of first window (loop omitted)', '    for s in range(n - m + 1):', '        if h == hp and text[s:s+m] == pat: return s', '        if s + m < n:', '            h = ((h - int(text[s]) * top) * B + int(text[s + m])) % M', '    return -1'];
  var c = ['int rabin_karp(const char *t, const char *p) {', '    int n = strlen(t), m = strlen(p), hp = 0, h = 0, top = pow_mod(B, m - 1, M);', '    /* hp, h = hash of pattern and of first window (loop omitted) */', '    for (int s = 0; s + m <= n; s++) {', '        if (h == hp && strncmp(t + s, p, m) == 0) return s;', '        if (s + m < n)', '            h = ((h - (t[s] - 48) * top % M + M) * B + (t[s + m] - 48)) % M;', '    } return -1; }'];

  window.LESSON = {
    id: 'rabin-karp',
    mode: 'ds',
    title: 'Rabin-Karp rolling hash',
    lede:
      'Rabin-Karp turns each window of the text into a single number (a hash) and compares numbers instead of characters. The trick is the rolling hash: sliding the window by one position needs only a subtraction, a shift and an addition, so each hash costs O(1). Equal hashes might be a collision, so a match is confirmed by comparing characters. Expected O(n + m); the real strength is searching for many patterns at once and plagiarism detection style problems.',
    scenes: [
      { id: 'rolling', title: 'Rolling the hash', blurb: 'Each window gets a hash from the previous one. Only windows whose hash matches are checked letter by letter.', trap: 'Forgetting that equal hashes do NOT prove equality: always verify. Also keep the arithmetic modular and non-negative: in C and Java (h - old * top) can go negative, so add M before taking the remainder. A tiny modulus (7 here) is for teaching; real code uses a large prime.', pyCode: py, cCode: c, predict: { q: 'Two windows have the same hash. What must the algorithm do?', options: ['Report a match', 'Compare the characters to confirm', 'Discard both windows'], answer: 1, why: 'Different strings can share a hash (a collision), so equal hashes only mean "worth checking".' }, steps: scene() },
    ],
    builtins: [
      ['hash(s)', 'Python built-in string hash: randomised per process, so not usable as a stable rolling hash.'],
      ['pow(b, e, m)', 'Modular exponentiation: computes top = B^(m-1) mod M quickly.'],
      ['ord(ch)', 'Character code, used as the digit value when the text is not numeric.'],
      ['hashlib.sha256', 'A cryptographic hash. Too slow and not rollable for this job.'],
      ['text[s:s+m] == pat', 'The verification step after a hash hit.'],
      ['set of pattern hashes', 'Multi-pattern search: look each window hash up in a set.'],
    ],
  };
})();
